course.theme_css:
@import url('https://fonts.googleapis.com/css2?family=Tiro+Bangla:ital@0;1&family=Anek+Bangla:wght@400;500;600;700&family=Scheherazade+New:wght@400;700&display=swap');

:root{
  --paper:#eef1ec; --sheet:#fbfcfa; --ink:#1c2a26; --mut:#56655f; --line:#d3dbd4;
  --ism:#24478f; --ism-bg:#e3e9f6;
  --fil:#a8326e; --fil-bg:#f6e3ed;
  --harf:#1f7a5a; --harf-bg:#dff0e8;
  --gold:#b8921c; --gold-bg:#f6efd6;
  --side:#18302a; --side-ink:#d9e4de;
  --ok:#1f7a5a; --bad:#b3261e;
  --r-s:6px; --r-m:12px;
  --bn:"Anek Bangla","Noto Sans Bengali",sans-serif;
  --bnh:"Tiro Bangla","Noto Serif Bengali",serif;
  --ar:"Scheherazade New","Noto Naskh Arabic","Amiri",serif;
}
body.dark{
  --paper:#111a17; --sheet:#17221e; --ink:#e3ebe6; --mut:#9fb0a8; --line:#2c3b35;
  --ism:#8fb0f0; --ism-bg:#1d2a45; --fil:#ee8fbf; --fil-bg:#3d1f30; --harf:#6fd3a8; --harf-bg:#173628;
  --gold:#e2c25a; --gold-bg:#332b12; --side:#0b1310; --side-ink:#c9d6cf;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important;animation:none!important}}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--bn);font-size:17px;line-height:1.75;display:flex;min-height:100vh}
.ar{font-family:var(--ar);font-size:1.3em;line-height:1.6;direction:rtl;unicode-bidi:isolate}
:focus-visible{outline:3px solid var(--gold);outline-offset:2px}
button{font-family:inherit;font-size:15px;cursor:pointer}

/* ---------- side ---------- */
nav#side{width:280px;flex:0 0 280px;background:var(--side);color:var(--side-ink);position:sticky;top:0;height:100vh;overflow-y:auto;padding:28px 20px 40px}
.brand{font-family:var(--bnh);font-size:28px;line-height:1.2;color:#fff;margin:0}
.brand-ar{font-family:var(--ar);font-size:22px;color:var(--gold);direction:rtl;margin:4px 0 18px}
.prog{height:6px;background:rgba(255,255,255,.12);border-radius:6px;overflow:hidden;margin:0 0 6px}
.prog i{display:block;height:100%;width:0;background:var(--gold);transition:width .4s}
.prog-t{font-size:13px;opacity:.75;margin-bottom:18px}
nav#side .chap{font-family:var(--bnh);font-size:15px;color:var(--gold);margin:18px 0 6px}
nav#side a{display:flex;gap:10px;align-items:baseline;color:var(--side-ink);text-decoration:none;padding:7px 10px;border-radius:var(--r-s);font-size:15px;line-height:1.4}
nav#side a:hover{background:rgba(255,255,255,.06)}
nav#side a.on{background:rgba(255,255,255,.12);color:#fff}
nav#side a .n{font-family:var(--bnh);opacity:.6;min-width:1.2em}
nav#side a.done .n::after{content:" ✓";color:var(--gold);opacity:1}
nav#side .soon{opacity:.45;padding:4px 10px;font-size:14px}
.side-tools{display:flex;gap:8px;margin-top:22px}
.side-tools button{flex:1;background:transparent;border:1px solid rgba(255,255,255,.25);color:var(--side-ink);border-radius:var(--r-s);padding:6px}
#menuBtn{display:none}

/* ---------- main ---------- */
main{flex:1;min-width:0;padding:48px 40px 90px}
.page{display:none;max-width:780px;margin:0 auto}
.page.on{display:block}
h1.lt{font-family:var(--bnh);font-weight:400;font-size:40px;line-height:1.2;margin:0}
.lt-ar{font-family:var(--ar);font-size:34px;color:var(--gold);direction:rtl;text-align:right;margin:2px 0 6px}
.lt-meta{color:var(--mut);font-size:15px;margin-bottom:28px}
h2.st{font-family:var(--bnh);font-weight:400;font-size:26px;margin:46px 0 14px;display:flex;align-items:center;gap:12px}
h2.st::before{content:"";width:22px;height:2px;background:var(--gold)}
h3{font-family:var(--bnh);font-weight:400;font-size:20px;margin:28px 0 8px}
p{margin:0 0 14px}
.recap{border-left:3px solid var(--gold);padding:4px 0 4px 16px;color:var(--mut);margin:0 0 10px}

/* the tablet: example box */
.lawh{background:var(--sheet);border:1px solid var(--line);outline:1px solid var(--gold);outline-offset:-7px;border-radius:2px;padding:26px 28px 18px;margin:12px 0 18px}
.lawh-tools{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-start;margin-bottom:14px}
.chip{border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:999px;padding:4px 14px;font-size:14px}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--sheet);border-color:var(--ink)}
.chip.ci[aria-pressed="true"]{background:var(--ism);border-color:var(--ism);color:#fff}
.chip.cf[aria-pressed="true"]{background:var(--fil);border-color:var(--fil);color:#fff}
.chip.ch[aria-pressed="true"]{background:var(--harf);border-color:var(--harf);color:#fff}
.chip.cg[aria-pressed="true"]{background:var(--gold);border-color:var(--gold);color:#fff}
ol.sents{list-style:none;margin:0;padding:0;counter-reset:s}
ol.sents>li{counter-increment:s;display:grid;grid-template-columns:1fr auto;gap:4px 16px;align-items:center;padding:10px 0;border-bottom:1px dashed var(--line)}
ol.sents>li:last-child{border-bottom:0}
ol.sents .sa{direction:rtl;text-align:right;font-family:var(--ar);font-size:30px;line-height:1.9}
ol.sents>li::after{content:counter(s,arabic-indic);font-family:var(--ar);font-size:22px;color:var(--gold);grid-column:2;grid-row:1}
ol.sents .sb{grid-column:1/3;color:var(--mut);font-size:15px;text-align:right;display:none}
.lawh.show-mean .sb{display:block}

/* words */
.w{border-radius:4px;padding:0 2px;cursor:pointer;transition:background .2s,color .2s;border-bottom:2px solid transparent}
.w:hover{border-bottom-color:var(--line)}
.show-types .w.i{color:var(--ism);background:var(--ism-bg)}
.show-types .w.f{color:var(--fil);background:var(--fil-bg)}
.show-types .w.h{color:var(--harf);background:var(--harf-bg)}
.show-types .w.cmp{background:linear-gradient(90deg,var(--ism-bg) 0 70%,var(--harf-bg) 70%)}
.w.hl{background:var(--gold-bg);border-bottom-color:var(--gold);color:var(--ink)}
.w.picked{outline:2px solid var(--ism);outline-offset:1px}
.w.right{outline:2px solid var(--ok)}
.w.wrong{outline:2px dashed var(--bad)}
.w.miss{outline:2px dotted var(--gold)}
#pop{position:absolute;z-index:50;background:var(--ink);color:var(--sheet);border-radius:var(--r-s);padding:8px 12px;font-size:14px;max-width:260px;box-shadow:0 6px 24px rgba(0,0,0,.25);display:none;line-height:1.5}
#pop b{font-family:var(--bnh);font-weight:400;font-size:16px}
.legend{display:flex;flex-wrap:wrap;gap:14px;font-size:14px;color:var(--mut);margin-top:6px}
.legend span::before{content:"";display:inline-block;width:12px;height:12px;border-radius:3px;margin-right:6px;vertical-align:-1px;background:var(--c)}

/* split table */
table{border-collapse:collapse;width:100%;margin:10px 0 18px;font-size:16px}
th,td{border-bottom:1px solid var(--line);padding:9px 10px;text-align:left;vertical-align:middle}
th{font-family:var(--bnh);font-weight:400;color:var(--mut);font-size:15px}
td .ar{font-size:1.45em}
table.split td{text-align:center}
table.split tr:first-child td{font-family:var(--ar);font-size:28px;direction:rtl}
table.split{direction:rtl}
.yes{color:var(--ok);font-weight:700}.no{color:var(--mut)}

/* marginal note, rule, mnemonic */
.note{border-left:4px solid var(--gold);background:var(--gold-bg);padding:12px 16px;margin:14px 0;border-radius:0 var(--r-s) var(--r-s) 0}
.note>b:first-child{font-family:var(--bnh);font-weight:400}
.rule{margin:18px 0;padding:18px 22px;border-top:2px solid var(--ink);border-bottom:2px solid var(--ink);text-align:center}
.rule .ar{display:block;font-size:30px;margin-bottom:6px}
.rule .en{color:var(--mut);font-size:14px}
.mnem{display:flex;gap:16px;align-items:center;margin:18px 0;padding:14px 18px;border:1px dashed var(--ink);border-radius:var(--r-m)}
.mnem .k{font-family:var(--bnh);font-size:22px;white-space:nowrap}
.groups{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin:12px 0}
.grp{padding:14px 16px;border-top:4px solid var(--c);background:var(--sheet)}
.grp h4{margin:0 0 4px;font-family:var(--bnh);font-weight:400;font-size:18px;color:var(--c)}
.grp>.ar{display:block;font-size:24px;text-align:right}
.grp p{font-size:15px;color:var(--mut);margin:0}

/* tree diagram (svg built inline) */
.diag{margin:16px 0;text-align:center}
.diag svg{max-width:100%;height:auto}
.chart{margin:10px 0 6px}
.chart .row{display:grid;grid-template-columns:80px 1fr 40px;align-items:center;gap:10px;margin:6px 0;font-size:15px}
.chart .bar{height:22px;border-radius:0 4px 4px 0;background:var(--c);width:0;transition:width .7s ease}
.chart .v{font-family:var(--bnh)}

/* exercises */
.ex{background:var(--sheet);border:1px solid var(--line);border-radius:var(--r-m);padding:18px 20px;margin:16px 0}
.ex>h3{margin:0 0 4px}
.ex .hint{color:var(--mut);font-size:14px;margin-bottom:12px}
.ex .q{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:8px 0;border-bottom:1px dashed var(--line)}
.ex .q:last-of-type{border-bottom:0}
.ex .q .qt{flex:1 1 260px}
.ex .q .ar{font-size:26px}
.btn{border:1px solid var(--ink);background:transparent;color:var(--ink);border-radius:var(--r-s);padding:5px 14px}
.btn.pri{background:var(--ink);color:var(--sheet)}
.btn.sel{background:var(--ink);color:var(--sheet)}
.btn.right{background:var(--ok);border-color:var(--ok);color:#fff}
.btn.wrong{background:var(--bad);border-color:var(--bad);color:#fff}
input.num{width:64px;padding:5px 8px;font-family:var(--bnh);font-size:17px;border:1px solid var(--line);border-radius:var(--r-s);background:var(--paper);color:var(--ink)}
select{font-family:var(--ar);font-size:20px;padding:2px 8px;border:1px solid var(--line);border-radius:var(--r-s);background:var(--paper);color:var(--ink)}
.fb{font-size:14px;min-height:1.2em;flex-basis:100%}
.fb.ok{color:var(--ok)}.fb.bad{color:var(--bad)}
.ex-foot{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-top:12px}
.score{font-family:var(--bnh);color:var(--mut)}
.tray{display:flex;flex-wrap:wrap;gap:8px;direction:rtl;padding:10px;border:1px dashed var(--line);border-radius:var(--r-s);min-height:56px;margin-bottom:12px}
.tok{font-family:var(--ar);font-size:24px;line-height:1.5;padding:2px 14px;border:1px solid var(--line);border-radius:var(--r-s);background:var(--paper);color:var(--ink)}
.tok.sel{border-color:var(--gold);box-shadow:0 0 0 2px var(--gold)}
.tok.right{border-color:var(--ok);background:var(--harf-bg)}
.tok.wrong{border-color:var(--bad);background:#f8dcd9;color:#7a1610}
.bins{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}
.bin{border:2px solid var(--c);border-radius:var(--r-s);min-height:96px;padding:6px 8px 10px}
.bin.drop{background:var(--gold-bg)}
.bin .bh{font-family:var(--bnh);color:var(--c);margin-bottom:4px;display:block;width:100%;text-align:left;background:none;border:0;padding:2px 0;font-size:16px}
.bin .bt{display:flex;flex-wrap:wrap;gap:6px;direction:rtl}
.taps .ar{font-size:30px;line-height:2}
textarea{width:100%;min-height:70px;font-family:var(--ar);font-size:24px;direction:rtl;padding:8px;border:1px solid var(--line);border-radius:var(--r-s);background:var(--paper);color:var(--ink)}

/* tense switcher */
.tense{background:var(--sheet);border:1px solid var(--line);border-radius:var(--r-m);padding:18px;margin:14px 0}
.tense .big{font-family:var(--ar);font-size:56px;text-align:center;direction:rtl;line-height:1.5;color:var(--fil)}
.tense .bm{text-align:center;color:var(--mut);margin-bottom:6px}
.tense .ctl{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}

/* split explorer */
.splitx{display:flex;flex-wrap:wrap;gap:10px;margin:10px 0;direction:rtl}
.splitx button{font-family:var(--ar);font-size:26px;border:1px solid var(--line);background:var(--sheet);color:var(--ink);border-radius:var(--r-s);padding:2px 16px}
.splitx-out{min-height:2.4em;padding:8px 12px;border-left:3px solid var(--harf);background:var(--sheet)}

/* tarkib tags */
.trk{display:flex;flex-wrap:wrap;gap:6px 10px;direction:rtl;justify-content:flex-start;margin:10px 0 16px;padding:14px;background:var(--sheet);border:1px solid var(--line);border-radius:var(--r-m)}
.tk{display:inline-flex;flex-direction:column;align-items:center;border-bottom:3px solid var(--c,var(--ink));padding:0 4px 4px}
.tk .ar{font-size:30px;line-height:1.7;color:var(--c,var(--ink))}
.tk small{font-family:var(--bn);direction:ltr;font-size:13px;color:var(--mut);line-height:1.3;text-align:center}
.trk-cap{flex-basis:100%;direction:ltr;text-align:left;color:var(--mut);font-size:14px}
/* flip box: one word, several forms */
.flip{background:var(--sheet);border:1px solid var(--line);border-radius:var(--r-m);padding:18px;margin:14px 0}
.flip .big{font-family:var(--ar);font-size:52px;text-align:center;direction:rtl;line-height:1.6;color:var(--ism)}
.flip .bm{text-align:center;color:var(--mut);margin-bottom:8px;min-height:1.6em}
.flip .ctl{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}
/* irab grid table */
table.irab th,table.irab td{text-align:center}
table.irab td:first-child{text-align:left}
.cell-raf{color:var(--ism)}.cell-nasb{color:var(--fil)}.cell-jarr{color:var(--harf)}.cell-jazm{color:var(--gold)}
.draft{display:inline-block;font-size:13px;border:1px solid var(--gold);color:var(--gold);border-radius:999px;padding:0 10px;margin-left:6px}
/* qr */
.qr{display:flex;gap:20px;align-items:center;margin:34px 0 10px;padding:18px;border:1px solid var(--line);border-radius:var(--r-m);background:var(--sheet)}
.qr svg{width:120px;height:120px;flex:0 0 120px;background:#fff;padding:6px;border-radius:6px}
.qr h3{margin:0 0 4px}
.qr p{margin:0;font-size:15px;color:var(--mut)}
.qr a{color:var(--ism)}

/* footer of lesson */
.lfoot{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:40px;padding-top:18px;border-top:1px solid var(--line)}

/* home */
.hero{padding:10px 0 8px}
.hero .lawh{margin-top:24px}
.hero-q{font-family:var(--bnh);font-size:20px;margin:0 0 10px}
.road{list-style:none;padding:0;margin:14px 0;counter-reset:r}
.road li{counter-increment:r;display:grid;grid-template-columns:44px 1fr;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}
.road li::before{content:counter(r,bengali);font-family:var(--bnh);font-size:26px;color:var(--gold);line-height:1.2}
.road li b{font-family:var(--bnh);font-weight:400;font-size:18px}
.road li span{display:block;color:var(--mut);font-size:15px}
.road li.now b::after{content:"  · এখন পড়ছ";color:var(--gold);font-size:14px}
.steps5{display:grid;grid-template-columns:repeat(5,1fr);gap:0;margin:12px 0;border:1px solid var(--line);border-radius:var(--r-m);overflow:hidden;background:var(--sheet)}
.steps5 div{padding:12px 10px;text-align:center;font-size:14px;border-right:1px solid var(--line)}
.steps5 div:last-child{border-right:0}
.steps5 b{display:block;font-family:var(--bnh);font-weight:400;font-size:17px}

@media (max-width:860px){
  body{display:block}
  nav#side{position:fixed;left:0;top:0;transform:translateX(-100%);transition:transform .25s;z-index:40;box-shadow:0 0 40px rgba(0,0,0,.3)}
  nav#side.open{transform:none}
  #menuBtn{display:block;position:fixed;top:12px;left:12px;z-index:45;background:var(--side);color:#fff;border:0;border-radius:var(--r-s);padding:8px 14px}
  main{padding:64px 18px 80px}
  h1.lt{font-size:31px}
  ol.sents .sa{font-size:25px}
  .steps5{grid-template-columns:1fr 1fr}
  .steps5 div{border-bottom:1px solid var(--line)}
  .lawh{padding:22px 16px 14px}
}
@media print{
  nav#side,#menuBtn,.lfoot,.lawh-tools,.ex-foot,.side-tools{display:none!important}
  body{background:#fff;display:block}
  main{padding:0}
  .page{display:none!important}.page.on{display:block!important}
  .lawh .sb{display:block}
  .ex{break-inside:avoid}
}

/* account, gates, score */
.userbtn{display:block;width:100%;text-align:left;margin:0 0 14px;padding:8px 12px;border-radius:var(--r-s);border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.06);color:#fff;font-family:var(--bn);font-size:15px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
nav#side a.locked{opacity:.5}
nav#side a.locked .n::after{content:" 🔒";opacity:1}
.agrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:16px 0}
.acard{background:var(--sheet);border:1px solid var(--line);border-radius:var(--r-m);padding:20px}
.acard h3{margin:0 0 10px}
.acard label{display:block;font-size:14px;color:var(--mut);margin:10px 0 4px}
.acard input{width:100%;padding:9px 11px;font-size:16px;font-family:var(--bn);border:1px solid var(--line);border-radius:var(--r-s);background:var(--paper);color:var(--ink)}
.acard .btn{margin-top:14px}
.linkbtn{background:none;border:0;color:var(--ism);text-decoration:underline;padding:0;margin-left:10px;font-size:14px}
.amsg{min-height:1.4em;margin-top:10px;font-size:15px;color:var(--ok)}
.amsg.bad{color:var(--bad)}
.gate{text-align:center;padding:70px 20px}
.gate-ic{font-size:44px;margin-bottom:6px}
.gate p{color:var(--mut)}
.lscore{margin:34px 0 10px;padding:18px 20px;border:2px solid var(--gold);border-radius:var(--r-m);background:var(--gold-bg)}
.lscore h3{margin:0 0 6px}
.ls-pct{font-family:var(--bnh);font-size:44px;line-height:1.1;color:var(--bad)}
.ls-pct.ok{color:var(--ok)}
.ls-save{font-size:14px;color:var(--mut);margin-left:10px}

/* --- LMS ফ্রেমের জন্য সমন্বয় --- */
body{display:block!important;min-height:0!important;background:transparent!important}
main,.lx-body{padding:0!important;max-width:none!important;margin:0!important}
.page{display:block!important}
.page > h1.lt:first-child{display:none}
.lfoot{display:none!important}

