(function(){
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const bn=n=>String(n).replace(/\d/g,d=>'০১২৩৪৫৬৭৮৯'[d]);
const PASS=70;
document.body.insertAdjacentHTML('afterbegin','<div id="pop" role="status"></div>');
const root=document.querySelector('.page');
const ORIGINAL=root.innerHTML;
function report(ex,ok,total){ex.dataset.ok=ok;ex.dataset.total=total;updateScore()}
function updateScore(){
  const exs=$$('.ex[data-kind]',root); if(!exs.length) return;
  const body=$('.lscore .ls-body',root); if(!body) return;
  const doneEx=exs.filter(x=>x.dataset.total);
  if(doneEx.length<exs.length){body.innerHTML='<p>'+bn(exs.length)+'টি অনুশীলনের '+bn(doneEx.length)+'টি করা হয়েছে। সবগুলো শেষ করলে ফল দেখাবে।</p>';return}
  const ok=doneEx.reduce((a,x)=>a+ +x.dataset.ok,0), tot=doneEx.reduce((a,x)=>a+ +x.dataset.total,0);
  const pct=Math.round(ok/tot*100), pass=pct>=PASS;
  body.innerHTML='<div class="ls-pct'+(pass?' ok':'')+'">'+bn(pct)+'%</div><p>'+bn(tot)+'টির মধ্যে '+bn(ok)+'টি সঠিক। '+(pass?'মাশাআল্লাহ!':'পাশ করতে কমপক্ষে '+bn(PASS)+'% লাগবে — আবার চেষ্টা করো।')+'</p><button class="btn" data-retry>অনুশীলন আবার করো</button>';
  $('[data-retry]',body).onclick=()=>{mount();window.scrollTo(0,0)};
  if(window.LMS) LMS.report(pct);
}
/* ---------- word popover ---------- */
const pop=$('#pop');
document.addEventListener('click',e=>{
  const w=e.target.closest('.lawh .w, .taps.checked .w');
  if(!w){if(!e.target.closest('#pop'))pop.style.display='none';return}
  const m=w.dataset.m, t=w.dataset.t;
  if(!m&&!t){pop.style.display='none';return}
  pop.innerHTML=(m?'<b>'+m+'</b>':'')+(t?'<div>'+t+'</div>':'');
  const r=w.getBoundingClientRect();
  pop.style.display='block';
  const pw=pop.offsetWidth;
  pop.style.left=Math.max(8,Math.min(window.scrollX+r.left+r.width/2-pw/2,window.scrollX+document.documentElement.clientWidth-pw-8))+'px';
  pop.style.top=(window.scrollY+r.bottom+8)+'px';
});

/* ---------- charts ---------- */
function runCharts(root){
  $$('[data-chart]',root).forEach(box=>{
    const el=root.querySelector('#'+box.dataset.chart);if(!el)return;
    const c={i:0,f:0,h:0};
    $$('.w',box).forEach(w=>{if(w.classList.contains('cmp')){c.i++;c.h++}else['i','f','h'].forEach(k=>{if(w.classList.contains(k))c[k]++})});
    const max=Math.max(c.i,c.f,c.h)||1,rows=[['i','ইসম','--ism'],['f','ফে\'ল','--fil'],['h','হরফ','--harf']];
    el.innerHTML=rows.map(([k,l,v])=>'<div class="row"><span>'+l+'</span><div><div class="bar" style="--c:var('+v+')" data-w="'+(c[k]/max*100)+'"></div></div><span class="v">'+bn(c[k])+'</span></div>').join('');
    requestAnimationFrame(()=>requestAnimationFrame(()=>$$('.bar',el).forEach(b=>b.style.width=b.dataset.w+'%')));
  });
}

/* ---------- components (run on each mounted lesson) ---------- */
function score(ex,ok,total){const s=$('.score',ex);if(s)s.textContent=bn(total)+'টির মধ্যে '+bn(ok)+'টি সঠিক'+(ok===total?' · মাশাআল্লাহ!':'');report(ex,ok,total)}
function fb(q,ok,msg){const f=$('.fb',q);if(!f)return;f.className='fb '+(ok?'ok':'bad');f.textContent=msg||(ok?'সঠিক।':'আবার ভাবো।')}
const AL=[['al','শুরুতে اَلْ'],['tn','তানভীন'],['jr','আগে হরফে জার'],['ta','গোল তা']];
const HURUF=['فِي','مِنْ','إِلَى','هَلْ','وَ'];
const T=[['كَتَبَ','লিখল · কাজটি আগেই হয়ে গেছে · মাযি','past'],['يَكْتُبُ','লিখছে / লিখবে · এখন হচ্ছে বা পরে হবে · মুযারি\'','now'],['سَيَكْتُبُ','লিখবে · سَـ যোগ হলে শুধু ভবিষ্যৎ · মুযারি\'','fut'],['اُكْتُبْ','লেখো · কাউকে কাজটি করতে বলা · আমর','fut']];

function init(root){
  $$('[data-toggle]',root).forEach(b=>b.onclick=()=>{const box=b.closest('.lawh');const on=box.classList.toggle(b.dataset.toggle);b.setAttribute('aria-pressed',on)});
  $$('[data-mark]',root).forEach(b=>b.onclick=()=>{
    const box=b.closest('.lawh'),k=b.dataset.mark,on=b.getAttribute('aria-pressed')!=='true';
    $$('[data-mark]',box).forEach(x=>x.setAttribute('aria-pressed','false'));
    $$('.w',box).forEach(w=>w.classList.remove('hl'));
    if(on){b.setAttribute('aria-pressed','true');$$('.w',box).forEach(w=>{if((w.dataset.al||'').split(' ').includes(k))w.classList.add('hl')})}
  });
  $$('.lawh .w',root).forEach(w=>{w.tabIndex=0;w.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();w.click()}})});
  $$('svg [fill^="var("], svg [stroke^="var("]',root).forEach(el=>['fill','stroke'].forEach(a=>{const v=el.getAttribute(a);if(v&&v.startsWith('var(')){el.style[a]=v;el.removeAttribute(a)}}));
  const tense=$('#tense',root);
  if(tense){
    $$('[data-t]',tense).forEach(b=>b.onclick=()=>{
      const t=T[b.dataset.t];$('#tWord',tense).textContent=t[0];$('#tMean',tense).textContent=t[1];
      $$('[data-t]',tense).forEach(x=>x.setAttribute('aria-pressed',x===b));
      $$('.tp',tense).forEach(c=>c.style.fill=c.dataset.p===t[2]?'var(--fil)':'var(--line)');
    });
    $$('.tp',tense).forEach(c=>c.style.fill=c.dataset.p==='past'?'var(--fil)':'var(--line)');
  }
  $$('.splitx button',root).forEach(b=>b.onclick=()=>{const [a,m]=b.dataset.s.split('|');let o=b.closest('.splitx').nextElementSibling;if(o&&o.classList.contains('splitx-out'))o.innerHTML='<span class="ar" style="font-size:26px">'+a+'</span> — '+m});
  $$('.flip',root).forEach(f=>{const bs=$$('.ctl button',f);const sh=b=>{$('.big',f).textContent=b.dataset.w;$('.bm',f).textContent=b.dataset.m||'';bs.forEach(x=>x.setAttribute('aria-pressed',x===b))};bs.forEach(b=>{b.classList.add('chip');b.onclick=()=>sh(b)});if(bs[0])sh(bs[0])});

  $$('.ex[data-kind=count]',root).forEach(ex=>{$('[data-check]',ex).onclick=()=>{let ok=0;const qs=$$('.q',ex);qs.forEach(q=>{const v=$('input',q).value.trim().replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d));const r=v===q.dataset.a;if(r)ok++;fb(q,r,r?'সঠিক।'+(q.dataset.x?' '+q.dataset.x:''):'হয়নি। আবার গুনে দেখো, জুড়ে লেখা শব্দসহ।')});score(ex,ok,qs.length)}});

  $$('.ex[data-kind=tf], .ex[data-kind=mcq]',root).forEach(ex=>{
    const qs=$$('.q',ex);let ok=0,ans=0;
    qs.forEach(q=>$$('button',q).forEach(b=>b.onclick=()=>{
      if(q.dataset.done)return;q.dataset.done=1;ans++;
      const right=ex.dataset.kind==='tf'?b.dataset.v===q.dataset.a:!!b.dataset.ok;
      b.classList.add(right?'right':'wrong');
      if(!right){$$('button',q).forEach(x=>{if(ex.dataset.kind==='tf'?x.dataset.v===q.dataset.a:x.dataset.ok)x.classList.add('right')})}
      if(right)ok++;
      fb(q,right,q.dataset.x||(right?'সঠিক।':'সঠিক উত্তরটি সবুজ করে দেখানো হলো।'));
      if(ans===qs.length)score(ex,ok,qs.length);
    }));
  });

  $$('.ex[data-kind=checks]',root).forEach(ex=>{
    const OPT=ex.dataset.opts?ex.dataset.opts.split('|').map(x=>x.split(':')):AL;
    $$('.q',ex).forEach(q=>{$('.opts',q).innerHTML=OPT.map(([k,l])=>'<button class="btn" data-k="'+k+'" aria-pressed="false">'+l+'</button>').join(' ');$$('[data-k]',q).forEach(b=>b.onclick=()=>{const on=!b.classList.contains('sel');b.classList.toggle('sel',on);b.setAttribute('aria-pressed',on)})});
    $('[data-check]',ex).onclick=()=>{let ok=0;const qs=$$('.q',ex);qs.forEach(q=>{const want=q.dataset.a.split(' ').sort().join(' '),got=$$('[data-k].sel',q).map(b=>b.dataset.k).sort().join(' ');const r=want===got;if(r)ok++;fb(q,r,r?'সঠিক।':'ঠিক উত্তর: '+q.dataset.a.split(' ').map(k=>(OPT.find(a=>a[0]===k)||[k,k])[1]).join(' ও '))});score(ex,ok,qs.length)};
  });

  $$('.ex[data-kind=fill]',root).forEach(ex=>{
    const OPTS=ex.dataset.opts?ex.dataset.opts.split('|'):HURUF;
    $$('select',ex).forEach(s=>s.innerHTML='<option value="">…</option>'+OPTS.map(h=>'<option>'+h+'</option>').join(''));
    $('[data-check]',ex).onclick=()=>{let ok=0;const qs=$$('.q',ex);qs.forEach(q=>{const r=$('select',q).value===q.dataset.a;if(r)ok++;fb(q,r,r?'সঠিক।':'এখানে আসবে '+q.dataset.a)});score(ex,ok,qs.length)};
  });

  $$('.ex[data-kind=tap]',root).forEach(ex=>{
    const ws=$$('.taps .w',ex),taps=$('.taps',ex);
    ws.forEach(w=>{w.tabIndex=0;w.setAttribute('role','button');w.onclick=()=>{if(taps.classList.contains('checked'))return;w.classList.toggle('picked')};w.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();w.click()}}});
    $('[data-check]',ex).onclick=()=>{let ok=0,tot=0,wrong=0;ws.forEach(w=>{const need=w.dataset.x==='1',p=w.classList.contains('picked');if(need)tot++;w.classList.remove('picked');if(need&&p){ok++;w.classList.add('right')}else if(need){w.classList.add('miss')}else if(p){w.classList.add('wrong');wrong++}});taps.classList.add('checked');
      $('.score',ex).textContent=bn(tot)+'টির মধ্যে '+bn(ok)+'টি ধরেছ'+(wrong?' · ভুল বাছাই '+bn(wrong)+'টি':'')+' · সবুজ = সঠিক, ডট = বাদ পড়েছে';
      report(ex,Math.max(0,ok-wrong),tot)};
    $('[data-reset]',ex).onclick=()=>{taps.classList.remove('checked');ws.forEach(w=>w.classList.remove('picked','right','wrong','miss'));$('.score',ex).textContent='';delete ex.dataset.total;delete ex.dataset.ok;const s=ex.closest('.page');if(s)updateScore(s)};
  });

  $$('.ex[data-kind=sort]',root).forEach(ex=>{
    const tray=$('.tray',ex),toks=$$('.tok',ex);let sel=null;
    const pick=t=>{if(sel)sel.classList.remove('sel');sel=(sel===t)?null:t;if(sel)sel.classList.add('sel')};
    const place=(t,bin)=>{t.classList.remove('sel','right','wrong');$('.bt',bin).appendChild(t);sel=null};
    toks.forEach(t=>{t.draggable=true;t.onclick=e=>{e.stopPropagation();if(t.parentElement!==tray&&!sel){tray.appendChild(t);t.classList.remove('right','wrong');return}pick(t)};t.ondragstart=e=>{sel=t;e.dataTransfer.setData('text','x')}});
    $$('.bin',ex).forEach(bin=>{
      bin.onclick=()=>{if(sel)place(sel,bin)};
      bin.ondragover=e=>{e.preventDefault();bin.classList.add('drop')};bin.ondragleave=()=>bin.classList.remove('drop');
      bin.ondrop=e=>{e.preventDefault();bin.classList.remove('drop');if(sel)place(sel,bin)};
    });
    $('[data-check]',ex).onclick=()=>{let ok=0;toks.forEach(t=>{const bin=t.closest('.bin');t.classList.remove('right','wrong');if(bin){const r=bin.dataset.b===t.dataset.a;t.classList.add(r?'right':'wrong');if(r)ok++}});const left=toks.filter(t=>!t.closest('.bin')).length;score(ex,ok,toks.length);if(left)$('.score',ex).textContent+=' · এখনো '+bn(left)+'টি বাকি'};
    $('[data-reset]',ex).onclick=()=>{toks.forEach(t=>{t.classList.remove('right','wrong','sel');tray.appendChild(t)});sel=null;$('.score',ex).textContent='';delete ex.dataset.total;delete ex.dataset.ok;const s=ex.closest('.page');if(s)updateScore(s)};
  });
}


function mount(){
  root.innerHTML=ORIGINAL;
  const panel=document.createElement('div');panel.className='lscore';panel.innerHTML='<h3>তোমার ফল</h3><div class="ls-body"></div>';
  const qr=$('.qr',root); if(qr) qr.before(panel); else root.appendChild(panel);
  init(root); runCharts(root); updateScore();
}
mount();
})();
